        nh_snprintf(__s_wielding_corpse, 636, cptr.decay(kbuf), 256n, __s_s_while_wielding_s, cptr.decay(hbuf), (yield* killer_xname(obj)));
        (yield* instapetrify(cptr.decay(kbuf)));
