            if (new_sex != orig_sex)
                (yield* discover_object(NHC.AMULET_OF_CHANGE, 1, 1, 1));
            (yield* on_msg(uamul.v));  /* show 'z - amulet of change (being worn)' */
            on_msg_done = 1;

